frame_view.original_source:
def frame_view(self):
    # A Koma special can generate sprites well outside the base character
    # pose. Frame the authored move *and* its source-resolved children
    # across the key span rather than only tick 0 (Goku Cheap Joke,
    # 0x5C12A, spawns two original 24-tick children at tick 7).
    rect = self._move_scope_extent()
    if rect:
        self.view.frame_rect(rect)
    else:
        self.view.frame_origin()

_move_scope_extent.original_source:
def _move_scope_extent(self):
    if not self.move:
        return None
    if not self.show_spawns.get() or not self.index:
        return self._move_extent()
    candidates = {0, self.tick}
    # Original character frame keys; include move extremes where available.
    for node in self.move.nodes:
        if node is None:
            continue
        for tr in node.tracks:
            if tr.field in ('BoundsIndex', 'TextureID', '2DPos', 'CollisionRect0') and tr.keyed:
                candidates.update(k.tick for k in tr.keys if 0 <= k.tick <= self.move.duration)
    for sp in spawns.keyed_spawns(self.move, self.almt.node_names):
        if sp.tick > self.move.duration:
            continue
        candidates.add(sp.tick)
        child = self._effect_moves.get(sp.effect_id)
        if child is not None:
            last = min(child[0].duration - 1, self.move.duration - sp.tick)
            if last > 0:
                candidates.add(sp.tick + last)
                candidates.add(sp.tick + last // 2)
    ticks = sorted(candidates)
    if len(ticks) > 48:
        # Deterministic sampling bounded for long/many-effect attacks.
        ticks = sorted({ticks[round(i * (len(ticks)-1)/47)] for i in range(48)}
                       | {0, self.tick})
    save_tick = self.tick
    extents = []
    try:
        for t in ticks:
            self.tick = t
            bounds = self._move_extent()
            if bounds:
                extents.append(bounds)
    finally:
        self.tick = save_tick
    # The original NoteTrack can also launch shot objects (action2).
    # These are not GN GenerateID children of the parent and would be
    # omitted from an otherwise complete effect-aware viewport frame.
    extents.extend(self._handler00_launch_extents())
    if not extents:
        return None
    return (min(v[0] for v in extents), min(v[1] for v in extents),
            max(v[2] for v in extents), max(v[3] for v in extents))

_handler00_launch_extents.original_source:
def _handler00_launch_extents(self):
    """Only original shot birth sprites and their authored 1-level GN keys.

    Uses original shot launch XY and image pixels. Deliberately excludes
    native projectile travel, contact termination and conditional exit.
    """
    if not self.show_shot_sources.get() or not self.index:
        return []
    bounds = []
    for ev in self._shot_events_current():
        if ev.handler != 0:
            continue
        origin_x, origin_y = self._animation_origin(ev.tick)
        base_x = origin_x + (-ev.launch_x if self.facing_left.get() else ev.launch_x)
        base_y = origin_y + ev.launch_y
        for rid in ev.directly_constructed_animations:
            entry = self._effect_moves.get(rid)
            if entry is None:
                continue
            child, child_names, _child_path = entry
            ages = {0, max(0, child.duration // 2), max(0, child.duration - 1)}
            for age in ages:
                tick = effectlinks.effect_frame_tick(child, age)
                if tick is None:
                    continue
                bounds.extend(spritegeometry.sprite_bounds(
                    self._state(child, tick).values(),
                    self._frame_image, (base_x, base_y)))
            for nested in spawns.keyed_spawns(child, child_names):
                nxt = self._effect_moves.get(nested.effect_id)
                if nxt is None or nested.tick >= child.duration:
                    continue
                nm, _nnames, _path = nxt
                at_tick = effectlinks.effect_frame_tick(nm, 0)
                if at_tick is None:
                    continue
                try:
                    ni = child_names.index(nested.node)
                except ValueError:
                    continue
                pos = spawns.state_at(child, nested.tick).get(ni, {}).get('2DPos', [0, 0])
                bounds.extend(spritegeometry.sprite_bounds(
                    self._state(nm, at_tick).values(), self._frame_image,
                    (base_x + pos[0], base_y + pos[1])))
    return bounds

_move_extent.original_source:
def _move_extent(self):
    if not self.move:
        return None
    xs = []
    st = self._state(self.move, self.tick)
    for s in st.values():
        xs.extend(spritegeometry.sprite_bounds((s,), self._frame_image))
        pos = s.get('2DPos', [0, 0])
        for field, value in s.items():
            if field.startswith('CollisionRect') and isinstance(value, list):
                xs.append((pos[0] + value[0], pos[1] + value[1],
                           pos[0] + value[2], pos[1] + value[3]))
    if self.show_spawns.get() and self.index:
        for inst in self._visible_spawn_instances(self.spawn_projection()):
            xs.extend(spritegeometry.sprite_bounds(
                self._state(inst.move, inst.sub_tick).values(),
                self._frame_image, inst.anchor))
    dx, dy = self._animation_origin(self.tick)
    xs = [(l + dx, t + dy, r + dx, b + dy) for l, t, r, b in xs]
    if self.show_motion.get() and self._motion and self._motion.commands:
        xs.extend((f.px[0], f.px[1], f.px[0], f.px[1]) for f in self._motion.frames)
    if not xs:
        return None
    return (min(r[0] for r in xs) - 8, min(r[1] for r in xs) - 8, max(r[2] for r in xs) + 8,
            max(r[3] for r in xs) + 8)

_animation_origin.original_source:
def _animation_origin(self, tick):
    if self.root_motion.get() and self._motion and self._motion.commands:
        frame = self._motion.at(tick)
        if frame:
            return frame.px
    return (0.0, 0.0)

spawn_projection.original_source:
def spawn_projection(self, tick=None):
    if not self.move or not self.almt:
        return spawns.Projection([], [], [])
    return spawns.project(self.move, self.almt.node_names, self.tick if tick is None else tick,
                          self._effect_moves, follow_parent=self.parent_link_preview.get(),
                          origin_at=self._animation_origin,
                          apply_teardown=self.effect_teardown.get())

_shot_events_current.original_source:
def _shot_events_current(self):
    """All original 0x0300/action2 shot invocations for this base battle AMT."""
    if not self.move or not self.almt or not self.root_data or not self._battle_base_table():
        return ()
    form, _ = self._move_source_form()
    if form is None:
        return ()
    member = join('chr/ChrBin.aar', f'chr/shot/{form}.bin')
    if not self.root_data.exists(member):
        return ()
    try:
        table = chrbin.parse(self.root_data.read(member), f'chr/shot/{form}.bin')
        return shotvisuals.source_shots(self.move, self.almt.node_names, table)
    except (ValueError, OSError, KeyError) as exc:
        self._shot_source_error = str(exc)
        return ()

_visible_spawn_instances.original_source:
def _visible_spawn_instances(self, projection):
    if not self.isolate_selected_spawn.get():
        return projection.instances
    hot = self.sel_virtual.get('spawn') if self.sel_virtual else None
    return [i for i in projection.instances if hot is not None and i.spawn == hot]
